  it('rejects an external article identity mismatch', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalArticleKey: 'article-other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'article-other' } }), validRequest), 'IDENTITY_MISMATCH') })
