describe('GEOFlow generation contract V1 — combined status events and lineage', () => {
  it('accepts initial queued event without previous response', () => { const result = validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'))); expect(result.ok).toBe(true) })
  it('rejects initial running event without previous response', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'))), 'INVALID_STATUS_TRANSITION') })
  it('accepts queued to running event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), responseForStatus('queued'))).ok).toBe(true) })
  it('accepts running to draft_ready event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeDraftResponse(validRequest, { status: 'draft_ready' }), responseForStatus('running'))).ok).toBe(true) })
  it('accepts running to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(validResponse, responseForStatus('running'))).ok).toBe(true) })
  it('accepts draft_ready to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(validResponse, responseForStatus('draft_ready'))).ok).toBe(true) })
  it('accepts review_required to blocked event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeFailureResponse(validRequest, 'blocked'), responseForStatus('review_required'))).ok).toBe(true) })
  it('accepts retry_wait to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:06:00.000Z'), makeRetryResponse(validRequest, 1), true)).ok).toBe(true) })
  it('accepts failed to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:02:00.000Z'), makeFailureResponse(validRequest, 'failed', 1, true), true)).ok).toBe(true) })
  it('rejects retry_wait to queued without explicit retry', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued'), '2026-08-25T04:06:00.000Z'), makeRetryResponse(), false)), 'INVALID_STATUS_TRANSITION') })
  it('rejects running to queued', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), responseForStatus('running'))), 'INVALID_STATUS_TRANSITION') })
  it('rejects an event with invalid previous response state', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), { ...makeProgressResponse(), status: 'unknown' })), 'UNKNOWN_STATE') })
  it('rejects an event with a published response', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent({ ...validResponse, status: 'published' })), 'UNKNOWN_STATE') })
  it('rejects an event with invalid request lineage', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), null, false, { ...validRequest, requestFingerprint: HASH_B })), 'REQUEST_FINGERPRINT_MISMATCH') })
  it('verifies a candidate response lineage', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true) })
  it('verifies a progress response lineage without content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeProgressResponse()).ok).toBe(true) })
  it('verifies a failure response lineage without content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeFailureResponse()).ok).toBe(true) })
  it('rejects candidate lineage with wrong article identity', () => { expectFailure(verifyGeoFlowLineage(validRequest, responseWith({ externalArticleKey: 'wrong', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'wrong' } })), 'IDENTITY_MISMATCH') })
  it('derives stable article identity from calendar entry and deliverable', () => { expect(deriveExternalArticleKey(validRequest)).toBe('article-101-303') })
  it('candidate identity matches request brief fingerprint', () => { expect(validResponse.draftIdentity.briefFingerprint).toBe(validRequest.briefFingerprint) })
  it('candidate identity does not use title as article identity', () => { expect(deriveExternalArticleKey(validRequest)).not.toContain(validRequest.brief.title) })
  it('response status remains candidate review_required', () => { expect(validResponse.status).toBe('review_required') })
  it('failure metadata contains only fixed code and retryable flag', () => { const failure = makeFailureResponse(); expect(Object.keys(failure.failure).sort()).toEqual(['code', 'retryable']) })
  it('progress metadata contains observedAt rather than completedAt', () => { const progress = makeProgressResponse(); expect('observedAt' in progress).toBe(true); expect('completedAt' in progress).toBe(false) })
  it('draft result contains content artifact rather than legacy top-level body fields', () => { expect('contentArtifact' in validResponse).toBe(true); expect('bodyMarkdown' in validResponse).toBe(false) })
  it('content artifact uses the fixed schema version', () => { expect(validResponse.contentArtifact.schemaVersion).toBe(CONTENT_ARTIFACT_SCHEMA_VERSION) })
})

describe('GEOFlow generation contract V1 — fixed HMAC envelope planner', () => {
  it('plans an envelope from request without bodyHash input', () => { const result = planSigningEnvelope(validEnvelopeInput); expect(result.ok).toBe(true); if (result.ok) expect(result.value.bodyHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('computes bodyHash from canonical request bytes', () => { const canonical = canonicalizeContractValue(validRequest); const envelope = plannedEnvelope(); expect(canonical.ok).toBe(true); if (canonical.ok) expect(envelope.bodyHash).toBe(sha256(canonical.value)) })
  it('rejects caller-supplied bodyHash planner field', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, bodyHash: HASH_A }), 'UNKNOWN_FIELD') })
  it('rejects missing keyId planner field', () => { const input = { ...validEnvelopeInput } as Record<string, unknown>; delete input.keyId; expectFailure(planSigningEnvelope(input), 'UNKNOWN_FIELD') })
  it('uses fixed hmac-sha256 algorithm', () => { const envelope = plannedEnvelope(); expect(envelope.algorithm).toBe(SIGNING_ALGORITHM) })
  it('uses fixed POST method', () => { const envelope = plannedEnvelope(); expect(envelope.method).toBe(SIGNING_METHOD) })
  it('uses fixed generation-jobs path', () => { const envelope = plannedEnvelope(); expect(envelope.path).toBe(SIGNING_PATH) })
  it('uses caller-injected timestamp', () => { const envelope = plannedEnvelope({ timestamp: '2026-08-25T04:03:00+08:00' }); expect(envelope.timestamp).toBe('2026-08-24T20:03:00.000Z') })
  it('uses caller-injected nonce', () => { const envelope = plannedEnvelope({ nonce: 'Z'.repeat(32) }); expect(envelope.nonce).toBe('Z'.repeat(32)) })
  it('rejects a short nonce', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: 'short' }), 'INVALID_INPUT') })
  it('rejects a nonce with non-base64url punctuation', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: `${'N'.repeat(31)}!` }), 'INVALID_INPUT') })
  it('rejects an overlong nonce', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: 'N'.repeat(129) }), 'INVALID_INPUT') })
  it('rejects a keyId with secret-like punctuation', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, keyId: 'token=secret' }), 'INVALID_OPAQUE_IDENTIFIER') })
  it('canonical signing input starts with algorithm', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.startsWith(`${SIGNING_ALGORITHM}\n`)).toBe(true) })
  it('canonical signing input includes method and path', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.split('\n').slice(0, 3)).toEqual([SIGNING_ALGORITHM, SIGNING_METHOD, SIGNING_PATH]) })
  it('canonical signing input has fixed field count', () => { expect(plannedEnvelope().canonicalSigningInput.split('\n')).toHaveLength(13) })
  it('canonical signing input binds request fingerprint', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput).toContain(validRequest.requestFingerprint) })
  it('canonical signing input binds body hash', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput).toContain(envelope.bodyHash) })
  it('canonical signing input binds keyId', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.endsWith('\nkey-1')).toBe(true) })
  it('canonical builder uses exact newline ordering', () => { const envelope = plannedEnvelope(); expect(buildCanonicalSigningInput(envelope as never)).toBe(envelope.canonicalSigningInput) })
  it('rejects an envelope extra field', async () => { await expectAsyncFailure(verifySigningEnvelope({ ...plannedEnvelope(), extra: true }, 'a'.repeat(64), signingContext()), 'UNKNOWN_FIELD') })
  it('rejects an envelope algorithm mutation', async () => { await expectAsyncFailure(verifySigningEnvelope({ ...plannedEnvelope(), algorithm: 'sha256' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope method mutation', async () => { await expectAsyncFailure(verifySigningEnvelope({ ...plannedEnvelope(), method: 'PUT' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope path mutation', async () => { await expectAsyncFailure(verifySigningEnvelope({ ...plannedEnvelope(), path: '/other' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope request identity mutation', async () => { const envelope = plannedEnvelope({ request: makeRequest({ requestId: 'req-002' }) }); await expectAsyncFailure(verifySigningEnvelope(envelope, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects a body hash mutation after canonical input update', async () => { const envelope = plannedEnvelope(); const bodyHash = HASH_A; const mutated = { ...envelope, bodyHash, canonicalSigningInput: buildCanonicalSigningInput({ ...envelope, bodyHash }) }; await expectAsyncFailure(verifySigningEnvelope(mutated, 'a'.repeat(64), signingContext()), 'CONTENT_HASH_MISMATCH') })
  it('accepts a valid synthetic signature verifier', async () => { expect((await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext())).ok).toBe(true) })
  it('rejects uppercase signature format', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'A'.repeat(64), signingContext()), 'INVALID_INPUT') })
  it('rejects short signature format', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(63), signingContext()), 'INVALID_INPUT') })
  it('rejects a signature with punctuation', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), `${'a'.repeat(63)}!`, signingContext()), 'INVALID_INPUT') })
  it('rejects a signature verifier mismatch', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => false })), 'IDENTITY_MISMATCH') })
  it('rejects a signature verifier exception', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => { throw new Error('signature') } })), 'IDENTITY_MISMATCH') })
  it('rejects sender context mismatch', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedSender: 'other-sender' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects receiver context mismatch', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedReceiver: 'other-receiver' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects keyId context mismatch', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedKeyId: 'other-key' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an expired timestamp', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ verificationTime: '2026-08-25T04:00:00Z', maxClockSkewSeconds: 60 })), 'SIGNATURE_EXPIRED') })
  it('rejects a future timestamp outside skew', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope({ timestamp: '2026-08-25T04:04:00Z' }), 'a'.repeat(64), signingContext({ verificationTime: '2026-08-25T04:02:00Z', maxClockSkewSeconds: 60 })), 'SIGNATURE_EXPIRED') })
  it('rejects a reused nonce', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: async () => false })), 'NONCE_REPLAYED') })
  it('rejects a throwing nonce claim verifier', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: async () => { throw new Error('nonce') } })), 'NONCE_REPLAYED') })
  it('rejects maxClockSkewSeconds below one', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ maxClockSkewSeconds: 0 })), 'INVALID_INPUT') })
  it('rejects maxClockSkewSeconds above 300', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ maxClockSkewSeconds: 301 })), 'INVALID_INPUT') })
  it('rejects context unknown fields', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ extra: true })), 'UNKNOWN_FIELD') })
  it('rejects a malformed verification time', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ verificationTime: 'tomorrow' })), 'INVALID_TIMESTAMP') })
  it('does not expose a secret field in envelope output', () => { expect('secret' in plannedEnvelope()).toBe(false) })
  it('does not expose authorization in envelope output', () => { expect('authorization' in plannedEnvelope()).toBe(false) })
  it('rejects a planner unknown field instead of ignoring it', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, secret: 'not-a-secret' }), 'UNKNOWN_FIELD') })
  it('accepts canonical signing input from fixed core', () => { const envelope = plannedEnvelope(); expect(buildCanonicalSigningInput(envelope as never).split('\n')[0]).toBe(SIGNING_ALGORITHM) })
  it('does not claim a nonce when signature is false', async () => { let claimCalls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => false, nonceClaimVerifier: () => { claimCalls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(claimCalls).toBe(0) })
  it('does not claim a nonce when signature verifier throws', async () => { let claimCalls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => { throw new Error('invalid signature') }, nonceClaimVerifier: () => { claimCalls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(claimCalls).toBe(0) })
  it('claims only after a valid signature', async () => { const calls: string[] = []; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => { calls.push('signature'); return true }, nonceClaimVerifier: (input: NonceClaimInput) => { calls.push(`claim:${input.sender}:${input.receiver}:${input.keyId}:${input.nonce}`); return true } })); expect(result.ok).toBe(true); expect(calls).toEqual(['signature', `claim:discoverystack-control-plane:geoflow-content-engine:key-1:${'N'.repeat(32)}`]) })
  it('passes the complete nonce scope to the atomic claim verifier', async () => { let received: NonceClaimInput | null = null; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: (input: NonceClaimInput) => { received = input; return true } })); expect(result.ok).toBe(true); expect(received).toEqual({ nonce: 'N'.repeat(32), sender: 'discoverystack-control-plane', receiver: 'geoflow-content-engine', keyId: 'key-1', timestamp: '2026-08-25T04:02:00.000Z' }) })
  it('returns NONCE_REPLAYED on the second claim for the same scope', async () => { const claimed = new Set<string>(); const claim = (input: NonceClaimInput) => { const scope = [input.sender, input.receiver, input.keyId, input.nonce].join('\u0000'); if (claimed.has(scope)) return false; claimed.add(scope); return true }; const context = signingContext({ nonceClaimVerifier: claim }); expect((await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), context)).ok).toBe(true); await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), context), 'NONCE_REPLAYED') })
  it('does not share nonce scope across sender or keyId', async () => { const claimed = new Set<string>(); const claim = (input: NonceClaimInput) => { const scope = [input.sender, input.receiver, input.keyId, input.nonce].join('\u0000'); if (claimed.has(scope)) return false; claimed.add(scope); return true }; const first = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: claim })); const secondEnvelope = plannedEnvelope({ sender: 'other-plane' }); const second = await verifySigningEnvelope(secondEnvelope, 'a'.repeat(64), signingContext({ expectedSender: 'other-plane', nonceClaimVerifier: claim })); expect(first.ok).toBe(true); expect(second.ok).toBe(true) })
  it('allows at most one success for concurrent same-scope claims', async () => { const claimed = new Set<string>(); const claim = async (input: NonceClaimInput) => { const scope = [input.sender, input.receiver, input.keyId, input.nonce].join('\u0000'); if (claimed.has(scope)) return false; claimed.add(scope); await Promise.resolve(); return true }; const results = await Promise.all([verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: claim })), verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: claim }))]); expect(results.filter(result => result.ok)).toHaveLength(1); expect(results.filter(result => !result.ok).map(result => result.ok ? '' : result.reason)).toEqual(['NONCE_REPLAYED']) })
  it('fails closed when atomic nonce claim rejects', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: async () => Promise.reject(new Error('store unavailable')) })), 'NONCE_REPLAYED') })
  it('records signature before nonce claim', async () => { const calls: string[] = []; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: async () => { calls.push('signature'); return true }, nonceClaimVerifier: async () => { calls.push('nonce-claim'); return true } })); expect(result.ok).toBe(true); expect(calls).toEqual(['signature', 'nonce-claim']) })
})
describe('GEOFlow generation contract V1 — combined status events and lineage', () => {
  it('accepts initial queued event without previous response', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'))).ok).toBe(true) })
  it('rejects initial running event without previous response', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'))), 'INVALID_STATUS_TRANSITION') })
  it('accepts queued to running event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), responseForStatus('queued'))).ok).toBe(true) })
  it('accepts running to draft_ready event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeDraftResponse(validRequest, { status: 'draft_ready' }), responseForStatus('running'))).ok).toBe(true) })
  it('accepts running to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(validResponse, responseForStatus('running'))).ok).toBe(true) })
  it('accepts draft_ready to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(validResponse, responseForStatus('draft_ready'))).ok).toBe(true) })
  it('accepts review_required to blocked event', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeFailureResponse(validRequest, 'blocked'), responseForStatus('review_required'))).ok).toBe(true) })
  it('accepts retry_wait to queued with explicit retry', () => { const current = atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:06:00.000Z'); expect(validateGeoFlowStatusEventForStoredState(storedEvent(current, makeRetryResponse(validRequest, 1), true)).ok).toBe(true) })
  it('accepts failed to queued with explicit retry', () => { const current = atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:02:00.000Z'); expect(validateGeoFlowStatusEventForStoredState(storedEvent(current, makeFailureResponse(validRequest, 'failed', 1, true), true)).ok).toBe(true) })
  it('rejects retry_wait to queued without explicit retry', () => { const current = atTime(makeProgressResponse(validRequest, 'queued'), '2026-08-25T04:06:00.000Z'); expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, makeRetryResponse(), false)), 'INVALID_STATUS_TRANSITION') })
  it('rejects running to queued', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), responseForStatus('running'))), 'INVALID_STATUS_TRANSITION') })
  it('rejects an invalid previous response state', () => { const previous = { ...makeProgressResponse(), status: 'unknown' }; expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), previous)), 'UNKNOWN_STATE') })
  it('rejects an event with a published response', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent({ ...validResponse, status: 'published' })), 'UNKNOWN_STATE') })
  it('rejects an event with request fingerprint mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued'), null, false, { ...validRequest, requestFingerprint: HASH_B })), 'REQUEST_FINGERPRINT_MISMATCH') })
  it('rejects an event with response request mismatch', () => { const current = { ...makeProgressResponse(validRequest, 'running'), requestId: 'other' }; expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, responseForStatus('queued'))), 'IDENTITY_MISMATCH') })
  it('rejects an event with evidence mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(responseWith({ evidenceSnapshotHash: HASH_B }), responseForStatus('running'))), 'EVIDENCE_SNAPSHOT_MISMATCH') })
  it('rejects an event with candidate article identity mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(responseWith({ externalArticleKey: 'other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'other' } }), responseForStatus('running'))), 'IDENTITY_MISMATCH') })
  it('rejects an event with an applied rule outside selection', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(responseWith({ appliedRuleIds: ['not-selected'] }), responseForStatus('running'))), 'APPLIED_RULE_OUTSIDE_SELECTION') })
  it('rejects a status event unknown field', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ ...storedEvent(makeProgressResponse(validRequest, 'queued')), extra: true }), 'UNKNOWN_FIELD') })
  it('rejects a status event null response', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(null)), 'INVALID_INPUT') })
  it('rejects a status event nonboolean retry flag', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ ...storedEvent(makeProgressResponse(validRequest, 'queued')), explicitRetry: 'yes' }), 'INVALID_INPUT') })
  it('accepts a verified candidate lineage', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true) })
  it('accepts progress lineage without a content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeProgressResponse()).ok).toBe(true) })
  it('accepts failure lineage without a content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeFailureResponse()).ok).toBe(true) })
  it('rejects candidate lineage with wrong external article key', () => { expectFailure(verifyGeoFlowLineage(validRequest, responseWith({ externalArticleKey: 'other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'other' } })), 'IDENTITY_MISMATCH') })
  it('derives the stable article key from server IDs', () => { expect(deriveExternalArticleKey(validRequest)).toBe('article-101-303') })
  it('does not derive article identity from brief title', () => { expect(deriveExternalArticleKey(validRequest)).not.toContain(validRequest.brief.title) })
  it('keeps candidate status review_required', () => { expect(validResponse.status).toBe('review_required') })
  it('keeps failure state separate from draft result', () => { expect('failure' in makeFailureResponse()).toBe(true); expect('contentArtifact' in makeFailureResponse()).toBe(false) })
  it('keeps progress state separate from draft result', () => { expect('observedAt' in makeProgressResponse()).toBe(true); expect('contentArtifact' in makeProgressResponse()).toBe(false) })
  it('keeps retry state separate from failure state', () => { expect('retry' in makeRetryResponse()).toBe(true); expect('failure' in makeRetryResponse()).toBe(false) })
  it('requires fixed candidate artifact schema version', () => { expect(validResponse.contentArtifact.schemaVersion).toBe(CONTENT_ARTIFACT_SCHEMA_VERSION) })
  it('preserves exact candidate body newline', () => { expect(validResponse.contentArtifact.bodyMarkdown).toBe(BODY_MARKDOWN) })
  it('preserves exact candidate body hash', () => { expect(validResponse.contentArtifact.bodyHash).toBe(BODY_HASH) })
  it('uses lowercase candidate body hash', () => { expect(validResponse.contentArtifact.bodyHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('uses lowercase chunk hash', () => { expect(validRequest.evidenceChunks[0]?.chunkHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('lineage success retains validated request evidence for correlation', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true); if (result.ok) expect(result.value.request.evidenceChunks).toHaveLength(1) })
  it('does not expose stack text in event failures', () => { const result = validateGeoFlowStatusEventForStoredState({ previousResponse: null, request: validRequest, response: { ...makeProgressResponse(validRequest, 'queued'), observedAt: 'invalid' }, explicitRetry: false }); expectFailure(result, 'INVALID_TIMESTAMP'); expect(JSON.stringify(result)).not.toContain('Error') })
  it('rejects terminal delivery vocabulary in a response', () => { expectFailure(validateGeoFlowResponse({ ...validResponse, status: 'delivered' }, validRequest), 'UNKNOWN_STATE') })
  it('rejects terminal delivery vocabulary in a status event', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent({ ...validResponse, status: 'delivered' }, validResponse)), 'UNKNOWN_STATE') })
  it('rejects a response with missing external project identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalProjectKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external task identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalTaskKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external job identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalJobKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external article identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalArticleKey: '', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: '' } }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('exports a deterministic response fingerprint', () => { const a = responseFingerprint(validResponse); const b = responseFingerprint(clone(validResponse)); expect(a).toEqual(b); if (a.ok && b.ok) expect(a.value).toMatch(/^[0-9a-f]{64}$/u) })
  it('binds article key on queued responses', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), externalArticleKey: 'wrong' }, validRequest), 'IDENTITY_MISMATCH') })
  it('binds article key on running responses', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(validRequest, 'running'), externalArticleKey: 'wrong' }, validRequest), 'IDENTITY_MISMATCH') })
  it('binds article key on retry responses', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), externalArticleKey: 'wrong' }, validRequest), 'IDENTITY_MISMATCH') })
  it('binds article key on blocked responses', () => { expectFailure(validateGeoFlowResponse({ ...makeFailureResponse(validRequest, 'blocked'), externalArticleKey: 'wrong' }, validRequest), 'IDENTITY_MISMATCH') })
  it('binds article key on failed responses', () => { expectFailure(validateGeoFlowResponse({ ...makeFailureResponse(), externalArticleKey: 'wrong' }, validRequest), 'IDENTITY_MISMATCH') })
  it('binds article key on draft responses', () => { expectFailure(validateGeoFlowResponse({ ...validResponse, externalArticleKey: 'wrong', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'wrong' } }, validRequest), 'IDENTITY_MISMATCH') })
  it('rejects previous project identity changes', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), { ...responseForStatus('running'), externalProjectKey: 'other' })), 'IDENTITY_MISMATCH') })
  it('rejects previous task identity changes', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), { ...responseForStatus('running'), externalTaskKey: 'other' })), 'IDENTITY_MISMATCH') })
  it('rejects previous job identity changes', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), { ...responseForStatus('running'), externalJobKey: 'other' })), 'IDENTITY_MISMATCH') })
  it('rejects previous article identity changes', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), { ...responseForStatus('running'), externalArticleKey: 'other' })), 'IDENTITY_MISMATCH') })
  it('rejects a running event older than the stored response', () => { const previous = atTime(makeProgressResponse(validRequest, 'running'), '2026-08-25T04:02:00.000Z'); const current = atTime(makeProgressResponse(validRequest, 'running'), '2026-08-25T04:01:00.000Z'); expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, previous)), 'RESPONSE_TIME_INVALID') })
  it('accepts an exact same-timestamp event replay', () => { const event = atTime(makeProgressResponse(validRequest, 'queued'), '2026-08-25T04:01:00.000Z'); expect(validateGeoFlowStatusEventForStoredState(storedEvent(event, event)).ok).toBe(true) })
  it('rejects same-timestamp payload changes', () => { const previous = atTime(makeProgressResponse(validRequest, 'queued'), '2026-08-25T04:01:00.000Z'); const current = atTime({ ...makeProgressResponse(validRequest, 'queued'), limitations: ['changed'] }, '2026-08-25T04:01:00.000Z'); expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, previous)), 'RESPONSE_TIME_INVALID') })
  it('rejects the removed previousStatus caller field', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'queued', request: validRequest, response: makeProgressResponse(validRequest, 'running'), explicitRetry: false }), 'UNKNOWN_FIELD') })
  it('rejects a previous response with mismatched request identity', () => { const previous = { ...responseForStatus('running'), requestId: 'other' }; expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running'), previous)), 'IDENTITY_MISMATCH') })
  it('rejects queued observedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeProgressResponse(validRequest, 'queued'), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects running observedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeProgressResponse(validRequest, 'running'), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects blocked observedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeFailureResponse(validRequest, 'blocked'), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects failed observedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeFailureResponse(validRequest, 'failed'), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects retry_wait observedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeRetryResponse(), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects draft_ready completedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(makeDraftResponse(validRequest, { status: 'draft_ready' }), '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects review_required completedAt before request createdAt', () => { expectFailure(validateGeoFlowResponse(atTime(validResponse, '2026-08-24T19:59:59Z'), validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects retryAt equal to observedAt', () => { const retry = { ...makeRetryResponse(), observedAt: '2026-08-25T04:01:00Z', retry: { attempt: 1, retryAt: '2026-08-25T04:01:00Z' } }; expectFailure(validateGeoFlowResponse(retry, validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects retryAt before observedAt', () => { const retry = { ...makeRetryResponse(), observedAt: '2026-08-25T04:01:00Z', retry: { attempt: 1, retryAt: '2026-08-25T04:00:59Z' } }; expectFailure(validateGeoFlowResponse(retry, validRequest), 'RESPONSE_TIME_INVALID') })
  it('rejects retry attempt zero', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: 0, retry: { attempt: 0, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects negative retry attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: -1, retry: { attempt: -1, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects retry attempt eleven', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: 11, retry: { attempt: 11, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects infinite retry attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: Number.POSITIVE_INFINITY, retry: { attempt: Number.POSITIVE_INFINITY, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects NaN retry attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: Number.NaN, retry: { attempt: Number.NaN, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects fractional retry attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: 1.5, retry: { attempt: 1.5, retryAt: '2026-08-25T04:05:00Z' } }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects blocked response with retryable true', () => { expectFailure(validateGeoFlowResponse({ ...makeFailureResponse(validRequest, 'blocked'), failure: { code: 'INVALID_INPUT', retryable: true } }, validRequest), 'INVALID_INPUT') })
  it('rejects duplicate requested capabilities', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, requestedCapabilities: ['human_review', 'human_review'] } as unknown), 'DUPLICATE_IDENTIFIER') })
  it('rejects duplicate selected rule IDs', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, selectedRuleIds: ['direct-answer-first', 'direct-answer-first'] }), 'DUPLICATE_IDENTIFIER') })
  it('rejects duplicate authority source IDs', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, authoritySourceIds: ['source-1', 'source-1'] }), 'DUPLICATE_IDENTIFIER') })
  it('rejects duplicate applied rule IDs', () => { expectFailure(validateGeoFlowResponse(responseWith({ appliedRuleIds: ['direct-answer-first', 'direct-answer-first'] }), validRequest), 'DUPLICATE_IDENTIFIER') })
  it('rejects duplicate citation identity', () => { const citation = validResponse.citationBindings[0]; expectFailure(validateGeoFlowResponse(responseWith({ citationBindings: [citation, citation] }), validRequest), 'DUPLICATE_EVIDENCE_IDENTITY') })
})
describe('GEOFlow generation contract V1 — exact verifier return types', () => {
  it('accepts a synchronous exact boolean true signature', async () => { expect((await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => true }))).ok).toBe(true) })
  it('accepts an asynchronous exact boolean true signature', async () => { expect((await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: async () => true }))).ok).toBe(true) })
  it('rejects a truthy string signature without claiming nonce', async () => { let calls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => 'yes', nonceClaimVerifier: () => { calls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(calls).toBe(0) })
  it('rejects a numeric one signature without claiming nonce', async () => { let calls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => 1, nonceClaimVerifier: () => { calls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(calls).toBe(0) })
  it('rejects an object signature without claiming nonce', async () => { let calls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => ({}), nonceClaimVerifier: () => { calls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(calls).toBe(0) })
  it('rejects a promised truthy string signature without claiming nonce', async () => { let calls = 0; const result = await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => Promise.resolve('yes'), nonceClaimVerifier: () => { calls += 1; return true } })); expectFailure(result, 'IDENTITY_MISMATCH'); expect(calls).toBe(0) })
  it('rejects a truthy string nonce claim as replayed', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: () => 'yes' })), 'NONCE_REPLAYED') })
  it('rejects a numeric one nonce claim as replayed', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: () => 1 })), 'NONCE_REPLAYED') })
  it('rejects an object nonce claim as replayed', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: () => ({ claimed: false }) })), 'NONCE_REPLAYED') })
  it('rejects a promised object nonce claim as replayed', async () => { await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceClaimVerifier: () => Promise.resolve({}) })), 'NONCE_REPLAYED') })
})

describe('GEOFlow generation contract V1 — attempt lineage', () => {
  it('requires a top-level attempt on every response family', () => { expect(makeProgressResponse().attempt).toBe(1); expect(makeRetryResponse().attempt).toBe(1); expect(makeFailureResponse().attempt).toBe(1); expect(makeDraftResponse().attempt).toBe(1) })
  it('accepts retry metadata when nested attempt equals top-level attempt', () => { expect(validateGeoFlowResponse(makeRetryResponse(validRequest, 2), validRequest).ok).toBe(true) })
  it('rejects retry metadata when nested attempt differs from top-level attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeRetryResponse(), attempt: 2 }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('accepts initial queued attempt one', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued', 1))).ok).toBe(true) })
  it('rejects initial queued attempt two', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'queued', 2))), 'RETRY_ATTEMPT_INVALID') })
  it('accepts queued attempt one to running attempt one', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running', 1), responseForStatus('queued', undefined, 1))).ok).toBe(true) })
  it('rejects queued attempt one to running attempt two', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running', 2), responseForStatus('queued', undefined, 1))), 'RETRY_ATTEMPT_INVALID') })
  it('accepts running attempt one to retry_wait attempt one', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(makeRetryResponse(validRequest, 1), responseForStatus('running', undefined, 1))).ok).toBe(true) })
  it('accepts retry_wait attempt one to queued attempt two with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:06:00Z'), makeRetryResponse(validRequest, 1), true)).ok).toBe(true) })
  it('rejects retry_wait attempt one to queued attempt one', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 1), '2026-08-25T04:06:00Z'), makeRetryResponse(validRequest, 1), true)), 'RETRY_ATTEMPT_INVALID') })
  it('rejects retry_wait attempt one to queued attempt three', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 3), '2026-08-25T04:06:00Z'), makeRetryResponse(validRequest, 1), true)), 'RETRY_ATTEMPT_INVALID') })
  it('rejects retry_wait attempt ten to queued attempt eleven', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 11), '2026-08-25T04:06:00Z'), makeRetryResponse(validRequest, 10), true)), 'RETRY_ATTEMPT_INVALID') })
  it('rejects retry_wait attempt ten to queued attempt one', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 1), '2026-08-25T04:06:00Z'), makeRetryResponse(validRequest, 10), true)), 'RETRY_ATTEMPT_INVALID') })
  it('accepts retryable failed attempt one to queued attempt two', () => { expect(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:02:00Z'), makeFailureResponse(validRequest, 'failed', 1, true), true)).ok).toBe(true) })
  it('rejects non-retryable failed to queued', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:02:00Z'), makeFailureResponse(validRequest, 'failed', 1, false), true)), 'RETRY_ATTEMPT_INVALID') })
  it('rejects retryable failed without explicit retry', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(atTime(makeProgressResponse(validRequest, 'queued', 2), '2026-08-25T04:02:00Z'), makeFailureResponse(validRequest, 'failed', 1, true), false)), 'INVALID_STATUS_TRANSITION') })
  it('rejects ordinary queued to running with explicit retry', () => { expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(makeProgressResponse(validRequest, 'running', 1), responseForStatus('queued', undefined, 1), true)), 'INVALID_STATUS_TRANSITION') })
  it('accepts the maximum ordinary attempt ten', () => { expect(validateGeoFlowResponse(makeProgressResponse(validRequest, 'running', 10), validRequest).ok).toBe(true) })
  it('rejects top-level attempt zero', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: 0 }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects top-level negative attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: -1 }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects top-level attempt eleven', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: 11 }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects top-level infinite attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: Number.POSITIVE_INFINITY }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects top-level NaN attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: Number.NaN }, validRequest), 'RETRY_ATTEMPT_INVALID') })
  it('rejects top-level fractional attempt', () => { expectFailure(validateGeoFlowResponse({ ...makeProgressResponse(), attempt: 1.5 }, validRequest), 'RETRY_ATTEMPT_INVALID') })
})

describe('GEOFlow generation contract V1 — immutable candidate lineage', () => {
  function candidateEvent(current: DraftResultResponse, previous: DraftResultResponse): ValidationResult<unknown> { return validateGeoFlowStatusEventForStoredState(storedEvent(current, previous)) }
  function priorCandidate(status: 'draft_ready' | 'review_required' = 'draft_ready'): DraftResultResponse { return atTime(makeDraftResponse(validRequest, { status }), '2026-08-25T04:01:00Z') }
  function laterCandidate(overrides: Partial<DraftResultResponse> = {}): DraftResultResponse { return atTime(makeDraftResponse(validRequest, { status: 'review_required', ...overrides }), '2026-08-25T04:02:00Z') }
  it('accepts an exact draft_ready to review_required candidate', () => { expect(candidateEvent(laterCandidate(), priorCandidate()).ok).toBe(true) })
  it('rejects body mutation even with a recomputed valid body hash', () => { const body = 'Changed body'; expectFailure(candidateEvent(laterCandidate({ contentArtifact: artifactWith({ bodyMarkdown: body, bodyHash: sha256(body) }) }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects title mutation', () => { expectFailure(candidateEvent(laterCandidate({ contentArtifact: artifactWith({ title: 'Changed title', bodyHash: BODY_HASH }) }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects summary mutation', () => { expectFailure(candidateEvent(laterCandidate({ contentArtifact: artifactWith({ summary: 'Changed summary', bodyHash: BODY_HASH }) }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects citation mutation', () => { const request = makeRequest({ requestedCapabilities: ['prompt_pack'], selectedRuleIds: [], authoritySourceIds: [], evidenceChunks: [] }); const previous = atTime(makeDraftResponse(request, { status: 'draft_ready' }), '2026-08-25T04:01:00Z'); const current = atTime(makeDraftResponse(request, { status: 'review_required', citationBindings: [{ sourceId: 'source-1', artifactId: 'other-artifact', chunkId: 'chunk-1', chunkHash: CHUNK_HASH }] }), '2026-08-25T04:02:00Z'); expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, previous, false, request)), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects applied rule mutation', () => { const request = makeRequest({ requestedCapabilities: ['prompt_pack'], selectedRuleIds: ['direct-answer-first', 'heading-structure'] }); const previous = atTime(makeDraftResponse(request, { status: 'draft_ready' }), '2026-08-25T04:01:00Z'); const current = atTime(makeDraftResponse(request, { status: 'review_required', appliedRuleIds: ['direct-answer-first', 'changed-rule'] }), '2026-08-25T04:02:00Z'); expectFailure(validateGeoFlowStatusEventForStoredState(storedEvent(current, previous, false, request)), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects provider or model mutation', () => { expectFailure(candidateEvent(laterCandidate({ providerProvenance: { provider: 'provider', model: 'changed-model', mode: 'provider', fallbackReason: null } }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('rejects limitations mutation', () => { expectFailure(candidateEvent(laterCandidate({ limitations: [DETERMINISTIC_SCAFFOLD_LIMITATION, 'Changed limitation'] }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('accepts a later timestamp with exact candidate content', () => { expect(candidateEvent(laterCandidate(), priorCandidate()).ok).toBe(true) })
  it('keeps draft_ready self-events immutable', () => { expectFailure(candidateEvent(laterCandidate({ status: 'draft_ready', contentArtifact: artifactWith({ summary: 'changed' }) }), priorCandidate()), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('keeps review_required self-events immutable', () => { expectFailure(candidateEvent(laterCandidate({ status: 'review_required', contentArtifact: artifactWith({ summary: 'changed' }) }), priorCandidate('review_required')), 'CANDIDATE_LINEAGE_MISMATCH') })
  it('allows a new revision request to carry a new candidate lineage', () => { const revisionRequest = makeRequest({ generationMode: 'revision', revisionContext: validRevisionDraft.revisionContext }); const candidate = makeDraftResponse(revisionRequest); expect(verifyGeoFlowLineage(revisionRequest, candidate).ok).toBe(true) })
})

describe('GEOFlow generation contract V1 — timestamp offset policy', () => {
  it('accepts Z and normalizes to UTC', () => { expect(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00Z' }).ok).toBe(true) })
  it('accepts explicit positive zero offset', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00+00:00' }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.createdAt).toBe('2026-08-25T04:00:00.000Z') })
  it('converts a negative half-hour offset correctly', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T12:00:00-05:30' }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.createdAt).toBe('2026-08-25T17:30:00.000Z') })
  it('accepts the practical positive fourteen-hour boundary', () => { expect(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00+14:00' }).ok).toBe(true) })
  it('accepts the practical negative fourteen-hour boundary', () => { expect(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00-14:00' }).ok).toBe(true) })
  it('rejects positive fourteen hours and one minute', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00+14:01' }), 'INVALID_TIMESTAMP') })
  it('rejects negative fourteen hours and one minute', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00-14:01' }), 'INVALID_TIMESTAMP') })
  it('rejects a twenty-three-hour offset', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00+23:59' }), 'INVALID_TIMESTAMP') })
  it('rejects the unknown negative zero offset', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, createdAt: '2026-08-25T04:00:00-00:00' }), 'INVALID_TIMESTAMP') })
})

describe('GEOFlow generation contract V1 — expanded public URL policy', () => {
  it('rejects source.test and its subdomain', () => { expectFailure(validatePublicHttpsUrl('https://source.test/evidence'), 'INVALID_PUBLIC_URL'); expectFailure(validatePublicHttpsUrl('https://api.source.test/evidence'), 'INVALID_PUBLIC_URL') })
  it('rejects example domains and subdomains', () => { for (const hostname of ['example.com', 'example.net', 'example.org', 'api.example.com']) expectFailure(validatePublicHttpsUrl(`https://${hostname}/evidence`), 'INVALID_PUBLIC_URL') })
  it('rejects home.arpa and its subdomain', () => { expectFailure(validatePublicHttpsUrl('https://home.arpa/evidence'), 'INVALID_PUBLIC_URL'); expectFailure(validatePublicHttpsUrl('https://router.home.arpa/evidence'), 'INVALID_PUBLIC_URL') })
  it('rejects a sensitive query value', () => { expectFailure(validatePublicHttpsUrl('https://evidence.routing.discoverystack.dev/evidence?ref=Bearer-secret'), 'INVALID_PUBLIC_URL') })
  it('rejects an encoded sensitive query value', () => { expectFailure(validatePublicHttpsUrl('https://evidence.routing.discoverystack.dev/evidence?ref=%42earer-%73ecret'), 'INVALID_PUBLIC_URL') })
  it('rejects case-variant sensitive query names', () => { expectFailure(validatePublicHttpsUrl('https://evidence.routing.discoverystack.dev/evidence?ToKeN=value'), 'INVALID_PUBLIC_URL') })
  it('rejects an encoded sensitive query name', () => { expectFailure(validatePublicHttpsUrl('https://evidence.routing.discoverystack.dev/evidence?%61%70%69%5F%6B%65%79=value'), 'INVALID_PUBLIC_URL') })
  it.each(['apikey', 'api-key', 'api_key', 'accessToken', 'privateKey', 'client_token', 'access.token', 'auth', 'sig'])('rejects credential query alias %s', name => { expectFailure(validatePublicHttpsUrl(`https://evidence.routing.discoverystack.dev/evidence?${name}=opaque-value`), 'INVALID_PUBLIC_URL') })
  it.each(['https://[::8.8.8.8]/evidence', 'https://[::ffff:8.8.8.8]/evidence', 'https://[::ffff:0:8.8.8.8]/evidence'])('rejects IPv4-embedded IPv6 form %s', locator => { expectFailure(validatePublicHttpsUrl(locator), 'PRIVATE_OR_SPECIAL_TARGET') })
  it.each(['https://[64:ff9b::808:808]/evidence', 'https://[ff02::1]/evidence', 'https://[2001::1]/evidence', 'https://[2001:2::1]/evidence', 'https://[2001:20::1]/evidence', 'https://[3ff1::1]/evidence'])('rejects additional special-use IPv6 form %s', locator => { expectFailure(validatePublicHttpsUrl(locator), 'PRIVATE_OR_SPECIAL_TARGET') })
  it('rejects the additional 2002 IPv6 range', () => { expectFailure(validatePublicHttpsUrl('https://[2002::1]/evidence'), 'PRIVATE_OR_SPECIAL_TARGET') })
  it('rejects the additional 3fff IPv6 range', () => { expectFailure(validatePublicHttpsUrl('https://[3fff::1]/evidence'), 'PRIVATE_OR_SPECIAL_TARGET') })
  it('rejects the additional 5f00 IPv6 range', () => { expectFailure(validatePublicHttpsUrl('https://[5f00::1]/evidence'), 'PRIVATE_OR_SPECIAL_TARGET') })
  it('accepts a normal global IPv6 address', () => { expect(validatePublicHttpsUrl('https://[2001:4860:4860::8888]/evidence').ok).toBe(true) })
  it('keeps a benign encoded query value accepted', () => { expect(validatePublicHttpsUrl('https://evidence.routing.discoverystack.dev/evidence?ref=section%2Done').ok).toBe(true) })
})

describe('GEOFlow generation contract V1 — nonce uniqueness scope', () => {
  it('treats the same nonce scope with a different timestamp as replayed', async () => { const claimed = new Set<string>(); const claim = (input: NonceClaimInput) => { const scope = [input.sender, input.receiver, input.keyId, input.nonce].join('\u0000'); if (claimed.has(scope)) return false; claimed.add(scope); return true }; const context = signingContext({ nonceClaimVerifier: claim }); expect((await verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), context)).ok).toBe(true); await expectAsyncFailure(verifySigningEnvelope(plannedEnvelope({ timestamp: '2026-08-25T04:03:00Z' }), 'a'.repeat(64), { ...context, verificationTime: '2026-08-25T04:03:00Z' }), 'NONCE_REPLAYED') })
})
